"""STATUS.md is generated by scripts/status.py, stays fresh, and work in progress is capped."""

from __future__ import annotations

from pathlib import Path

import capabilities
import pytest
import status

ROOT = Path(__file__).parents[2]


def test_committed_status_page_is_fresh() -> None:
    committed = (ROOT / status.PAGE).read_text(encoding="utf-8")
    assert committed == status.render(ROOT), (
        "STATUS.md is stale; run: uv run python scripts/status.py"
    )


def test_check_mode_passes_on_the_committed_tree() -> None:
    assert status.main(["--check"]) == 0


def test_work_in_progress_stays_within_the_ratchet() -> None:
    """Live plans In progress or awaiting qualification may not exceed the ceiling.

    While the ceiling is above the limit it must equal the current count, so every piece of
    work that closes lowers it; once it reaches the limit the rule is simply count <= limit.
    """
    wip = status.read_wip_limit(ROOT)
    count = status.wip_count(capabilities.load(ROOT))
    assert count <= wip.ceiling, (
        f"{count} pieces of work in progress, above the ceiling of {wip.ceiling} in "
        f"{status.WIP_FILE}: finish or close work before starting more"
    )
    if wip.ceiling > wip.limit:
        assert wip.ceiling == count, (
            f"work closed: lower 'ceiling' in {status.WIP_FILE} from {wip.ceiling} to "
            f"{max(count, wip.limit)}"
        )


def test_page_shows_the_count_against_the_limit() -> None:
    wip = status.read_wip_limit(ROOT)
    count = status.wip_count(capabilities.load(ROOT))
    assert f"{count} in progress (limit {wip.limit})" in status.render(ROOT)


def test_page_sections_appear_in_the_agreed_order() -> None:
    text = status.render(ROOT)
    headings = [line for line in text.splitlines() if line.startswith("## ")]
    assert headings == [
        "## At a glance",
        "## What works today",
        "## Partly working",
        "## Known defects",
        "## Demo only",
        "## Shelved",
        "## Not started",
        "## In progress now",
        "## Waiting for your decision",
        "## Next up",
        "## Housekeeping",
        "## Where things are",
    ]
    assert text.splitlines()[2] == f"_Generated — do not edit; run: `{status.COMMAND}`_"


def test_every_capability_and_undecided_card_is_on_the_page() -> None:
    cmap = capabilities.load(ROOT)
    text = status.render(ROOT)
    for cap in cmap.capabilities:
        assert f"**{cap.label}**" in text, cap.id
    for _, triage in cmap.triage_items():
        if not triage.decided:
            assert f"- Card {triage.card}: " in text


@pytest.mark.parametrize(
    ("raw", "message"),
    [
        ('{"limit": 3}', "exactly"),
        ('{"limit": 3, "ceiling": 2}', "limit <= ceiling"),
        ('{"limit": "3", "ceiling": 4}', "whole numbers"),
        ("not json", "cannot read"),
    ],
)
def test_wip_limit_file_is_validated(tmp_path: Path, raw: str, message: str) -> None:
    target = tmp_path / status.WIP_FILE
    target.parent.mkdir(parents=True)
    target.write_text(raw, encoding="utf-8")
    with pytest.raises(status.StatusError, match=message):
        status.read_wip_limit(tmp_path)


def test_working_is_defined_as_run_end_to_end_through_the_installed_program() -> None:
    text = status.render(ROOT)
    assert (
        '"Working" means the workflow was run from start to finish through the installed program\n'
        "on made-up (synthetic) data." in text
    )
    cmap = capabilities.load(ROOT)
    for cap in cmap.capabilities:
        if cap.state == "Working":
            assert cap.proof_smoke and not cap.needs, cap.id


def test_known_defects_are_counted_and_listed() -> None:
    cmap = capabilities.load(ROOT)
    text = status.render(ROOT)
    section = text.split("## Known defects", 1)[1].split("\n## ", 1)[0]
    for defect in cmap.known_defects:
        assert f"- **{defect.title}.** To see it: {defect.how_to_reproduce}." in section
    if not cmap.known_defects:
        assert "- None known." in section
    assert f"- **Known defects:** {len(cmap.known_defects)}" in text


def test_in_process_only_items_are_grouped_without_repeating_the_phrase() -> None:
    text = status.render(ROOT)
    partly = text.split("## Partly working", 1)[1].split("\n## ", 1)[0]
    assert capabilities.NO_SMOKE_YET not in partly
    cmap = capabilities.load(ROOT)
    untried = [c for c in cmap.capabilities if status._tested_without_smoke(c)]
    if untried:
        group = partly.split("not yet run from start to finish", 1)[1]
        for cap in untried:
            assert f"**{cap.label}**" in group, cap.id
